function [a] = fsw_default_detumble(can)
%FSW_DEFAULT_DETUMBLE  The detumble algorithm a product flies when neither it nor the scenario names one: the gyro-fed B-dot, else the
%   magnetometer's, else none. can[k]: 1 when the product carries every device option k needs (the registry's needs).
%   can: int[4] (passed a whole number)
%   returns a: DetumbleAlg (passed a choice, as its option's number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    a = 0;
    a = 4;
    if (can(1) == 1)
        a = 0;
    elseif (can(2) == 1)
        a = 1;
    end
end
